 @property
 def coverage_ratio(self) -> float:
 """P90/P10 比值（越接近1越确定）"""
 if self.lower <= 0:
 return float("inf")
 return round(self.upper / self.lower, 4)

 def contains(self, actual: float) -> bool:
 return self.lower <= actual <= self.upper

