 pref = self.store.get(user_id)
 if not pref:
 return candidates
 def score(item: dict) -> float:
 s = pref.brand_prefs.get(item.get("brand", ""), 0)
 if any(f in item.get("features", []) for f in pref.disliked_features):
 s -= 2.0
 return s
 return sorted(candidates, key=score, reverse=True)

