 features = {}
 for item in items:
 features[item] = {
 "visual": rng.standard_normal(64), # 图像 embedding（实际 512dim）
 "text": rng.standard_normal(64), # 文本 embedding（实际 768dim）
 "review": rng.standard_normal(64), # 评论聚合 embedding
 }
