 if relative_seconds > 0:
 return None
 if tp.click_time < t0 - window:
 return None
 return relative_seconds

def pvm_attribution(conversion: Conversion, windows: Dict[str, timedelta] = None) -> Dict[str, float]:
 """Peer-Validated Mechanism: 信用按时序加权,sum <= 1"""
