@dataclass
class UserSegment:
 """用户分群的促销响应特征"""
 segment_id: str
 segment_name: str
 n_users: int # 该分群用户数
 propensity_to_respond: float # 绝对响应概率 P(buy | promo)
 baseline_response: float # 无促销响应概率 P(buy | no promo)
 expected_value: float # 响应后期望 LTV 增量（$）
