 """
 添加表结构

 Args:
 name: 表名
 columns: {字段名: 字段描述}
 description: 表用途描述
 """
 self.tables[name] = {
 &#x27;columns&#x27;: columns,
 &#x27;description&#x27;: description
 }

 def get_schema_prompt(self) -> str:
 """生成Schema描述Prompt"""
 lines = ["数据库Schema:"]
